'use client';

import type { EditorValueInput, Value } from 'platejs';
import type { CommentThread } from 'platejs/comments';
import { CommentsPlugin } from 'platejs/comments/react';
import { Plate, useCreateEditor } from 'platejs/react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { BasicBlocksKit } from '@/registry/components/editor/basic-blocks';
import { CommentComposer } from '@/registry/components/editor/comment';
import { CommentToolbarButton } from '@/registry/components/editor/comment-toolbar-button';
import { DiscussionKit } from '@/registry/components/editor/discussion';
import { Editor, EditorContainer } from '@/registry/components/editor/editor';
import { LinkKit } from '@/registry/components/editor/link';
import { SuggestionKit } from '@/registry/components/editor/suggestion';
import { Toolbar } from '@/registry/components/editor/toolbar';
import {
  commentThreads,
  commentUsers,
  commentValue,
} from '@/registry/examples/values/comment-value';

export default function CommentPersistenceDemo() {
  const [saved, setSaved] = React.useState<{
    document: EditorValueInput<Value>;
    threads: readonly CommentThread[];
  } | null>(null);
  const [loaded, setLoaded] = React.useState<{
    document: EditorValueInput<Value>;
    threads: readonly CommentThread[];
  }>({
    document: commentValue,
    threads: commentThreads,
  });
  const [failNext, setFailNext] = React.useState(true);
  const [status, setStatus] = React.useState(
    'Snapshots stay in memory in this example.'
  );
  const editor = useCreateEditor(
    {
      plugins: [
        ...BasicBlocksKit,
        ...LinkKit,
        ...SuggestionKit,
        ...DiscussionKit,
        CommentsPlugin.configure({
          initialState: {
            currentUserId: 'alice',
            users: commentUsers,
            initialThreads: loaded.threads,
          },
        }),
      ],
      initialValue: loaded.document,
    },
    [loaded]
  );

  return (
    <Plate editor={editor} key={editor.id}>
      <div className="flex w-full flex-col gap-4 p-4 sm:p-6">
        <div className="flex flex-wrap gap-2">
          <Button
            onClick={() => {
              setSaved(
                structuredClone({
                  document: editor.read.value(),
                  threads: editor.plugin(CommentsPlugin).api.getThreads(),
                })
              );
              setStatus('Saved the document and its comments in memory.');
            }}
            size="sm"
            variant="outline"
          >
            Save snapshot
          </Button>
          <Button
            disabled={!saved}
            onClick={() => {
              if (!saved) return;
              setLoaded(structuredClone(saved));
              setStatus(
                'Reloaded the saved snapshot. Unsaved changes were discarded.'
              );
            }}
            size="sm"
            variant="outline"
          >
            Reload snapshot
          </Button>
        </div>
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {status}
        </p>
        <EditorContainer className="h-[280px] rounded-md border" variant="demo">
          <Toolbar className="border-b px-3 py-1">
            <CommentToolbarButton />
          </Toolbar>
          <Editor
            aria-label="Saved comments document"
            className="h-auto min-h-[240px] px-8 pb-12 sm:px-12"
            variant="demo"
          />
        </EditorContainer>
        <div className="flex flex-col gap-3 rounded-md border p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-sm font-medium">Try a failed reply</p>
            <Button
              disabled={failNext}
              onClick={() => setFailNext(true)}
              size="sm"
              variant="outline"
            >
              Simulate next failure
            </Button>
          </div>
          <p className="text-sm text-muted-foreground">
            Reply to Charlie’s thread.{' '}
            {failNext
              ? 'The next send will fail; send again to retry with your draft intact.'
              : 'The next send will succeed.'}
          </p>
          <CommentComposer
            ariaLabel="Reply with simulated failure"
            onSubmit={async (body) => {
              if (failNext) {
                setFailNext(false);
                return false;
              }
              const result = await editor
                .plugin(CommentsPlugin)
                .api.reply('discussion1', body);
              if (result) {
                editor.plugin(CommentsPlugin).api.setActive(['discussion1']);
                setStatus(
                  'Reply added. Save a snapshot to keep it for reload.'
                );
              }
              return result;
            }}
            placeholder="Write a reply, then try sending it twice..."
          />
        </div>
      </div>
    </Plate>
  );
}

import type { Value } from 'platejs';
import type { CommentThread, CommentUser } from 'platejs/comments';

import { createCommentValue } from '@/registry/components/editor/comment';

export const commentUsers: Record<string, CommentUser> = {
  alice: {
    id: 'alice',
    name: 'Alice',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=alice6',
  },
  bob: {
    id: 'bob',
    name: 'Bob',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=bob4',
  },
  charlie: {
    id: 'charlie',
    name: 'Charlie',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=charlie2',
  },
};

const trailingText =
  ' on many text segments. You can even have overlapping annotations!';

export const commentValue: Value = [
  { type: 'heading', level: 2, children: [{ text: 'Comments' }] },
  {
    type: 'paragraph',
    children: [
      { text: 'Discuss changes using ' },
      { type: 'link', url: '/docs/comment', children: [{ text: 'comments' }] },
      { text: trailingText },
    ],
  },
  {
    type: 'paragraph',
    children: [{ text: 'Select some text and add your own comment as Alice.' }],
  },
];

export const commentThreads: CommentThread[] = [
  {
    id: 'discussion1',
    createdAt: '2026-09-10T10:00:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'comments on many text segments',
    userId: 'charlie',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 1, 0], offset: 0 },
        focus: { path: [1, 2], offset: trailingText.indexOf('.') },
      },
    },
    messages: [
      {
        id: 'discussion1-comment',
        userId: 'charlie',
        createdAt: '2026-09-10T10:00:00.000Z',
        body: createCommentValue(
          'Comments are a great way to provide feedback and discuss changes.'
        ),
      },
      {
        id: 'discussion1-reply',
        userId: 'bob',
        createdAt: '2026-09-10T10:02:00.000Z',
        body: createCommentValue(
          'Agreed! The link to the docs makes it easy to learn more.'
        ),
      },
    ],
  },
  {
    id: 'discussion2',
    createdAt: '2026-09-10T10:05:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'overlapping',
    userId: 'bob',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 2], offset: trailingText.indexOf('overlapping') },
        focus: {
          path: [1, 2],
          offset: trailingText.indexOf('overlapping') + 'overlapping'.length,
        },
      },
    },
    messages: [
      {
        id: 'discussion2-comment',
        userId: 'bob',
        createdAt: '2026-09-10T10:05:00.000Z',
        body: createCommentValue(
          'Nice demonstration of overlapping annotations with both comments and suggestions!'
        ),
      },
      {
        id: 'discussion2-reply',
        userId: 'charlie',
        createdAt: '2026-09-10T10:07:00.000Z',
        body: createCommentValue(
          'This helps users understand how powerful the editor can be.'
        ),
      },
    ],
  },
];
